command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="eccc723ce730b49be79626cf2e5794d1e2a9fabc"
$candidate="af12c918bd4e2f3d1138cc6334c0c82763269a5d"
$branch="work/metadata-sort-correctness-20261006"
$baselineProduct="4e59a22c742c7fa8d5d0e21e221f01ff8151e2be"
$baselineRuntime="C:\dev\flyExplorer\logs\f5-f6-runtime-4e59a22c"
$temp=Join-Path $env:RUNNER_TEMP ("fly-metadata-sort-"+$env:GITHUB_RUN_ID)
$cache="C:\dev\flyExplorer\logs\metadata-sort-runtime-"+$candidate.Substring(0,8)
$evidence=Join-Path $repo "logs\remote-evidence"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "metadata-sort fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before metadata-sort validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "metadata-sort branch moved before validation"}
if(Test-Path -LiteralPath $temp){throw "metadata-sort temp worktree already exists"}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "metadata-sort worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  $range=$main+"..."+$candidate
  & git diff --check $range
  if($LASTEXITCODE -ne 0){throw "metadata-sort diff check failed"}

  $baselineExe=Join-Path $baselineRuntime "flyExplorer.exe"
  Set-Location -LiteralPath $repo
  & git diff --quiet ($baselineProduct+".."+$main) -- app/winui src/base build.bat run.bat
  $baselineEquivalent=($LASTEXITCODE -eq 0)
  Set-Location -LiteralPath $temp
  if((Test-Path -LiteralPath $baselineExe) -and $baselineEquivalent){
    & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --exe $baselineExe --expect-legacy-fallback --capture before
    if($LASTEXITCODE -ne 0){throw "metadata-sort BEFORE acceptance failed"}
    Write-Host "METADATA_SORT_BEFORE_ACCEPTANCE=PASS"
  }else{
    throw "exact current-main product-equivalent baseline runtime unavailable"
  }

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "metadata-sort Release build failed"}
  Write-Host "METADATA_SORT_RELEASE_BUILD=PASS"

  if(Test-Path -LiteralPath $cache){Remove-Item -LiteralPath $cache -Recurse -Force}
  New-Item -ItemType Directory -Path $cache -Force | Out-Null
  Copy-Item -Path (Join-Path $temp "out\winui\Release\*") -Destination $cache -Recurse -Force
  if(!(Test-Path -LiteralPath (Join-Path $cache "flyExplorer.exe"))){throw "metadata-sort runtime cache missing executable"}
  Write-Host ("METADATA_SORT_RUNTIME_CACHE="+$cache)

  & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --capture after
  if($LASTEXITCODE -ne 0){throw "metadata-sort focused GUI acceptance failed"}
  Write-Host "METADATA_SORT_FOCUSED_GUI=PASS"

  New-Item -ItemType Directory -Path $evidence -Force | Out-Null
  Copy-Item -LiteralPath (Join-Path $temp "logs\metadata-sort\metadata-sort-before.png") -Destination (Join-Path $evidence "metadata-sort-before.png") -Force
  Copy-Item -LiteralPath (Join-Path $temp "logs\metadata-sort\metadata-sort-after.png") -Destination (Join-Path $evidence "metadata-sort-after.png") -Force
  Write-Host "METADATA_SORT_VISUAL_EVIDENCE=EXPORTED"
  Write-Host "METADATA_SORT_ACCEPTANCE=PASS"
} finally {
  Set-Location -LiteralPath $repo
  & git worktree remove $temp --force
}
